style.css:
@-moz-document domain("youtube.com") {
body, ytd-app {
        background: #1a1a1a !important;
        color: #b3b3b3 !important;
    }

    /* Main content area (video container) */
    ytd-masthead, ytd-video-primary-info-renderer, ytd-page-manager {
        background: #0d0d0d !important;
        border: 1px solid #222 !important;
        box-shadow: 0 0 20px rgba(0, 0, 0, 0.8) !important;
    }

    /* Video player area */
    ytd-player {
        background: #2e2e2e !important;
        border: 1px solid #444 !important;
        box-shadow: 0 0 25px rgba(0, 0, 0, 0.8) !important;
    }

    /* Text color for headings and video titles */
    h1, h2, h3, ytd-video-title, ytd-video-secondary-info-renderer {
        color: #e0e0e0 !important;
    }

    /* Sidebar (recommended videos) */
    #related {
        background: #262626 !important;
        border: 1px solid #444 !important;
    }

    /* Buttons (play, pause, etc.) */
    ytd-video-primary-info-renderer, ytd-button-renderer, yt-icon-button {
        background: #2b2b2b !important;
        color: #e0e0e0 !important;
        border-radius: 5px;
    }

    yt-icon {
        filter: brightness(0) invert(1) !important;
    }

    /* Set a nuclear glow for hover effects */
    a:hover, ytd-thumbnail.ytd-video-renderer:hover, ytd-button-renderer:hover {
        background: rgba(255, 0, 0, 0.3) !important;
        border: 1px solid rgba(255, 0, 0, 0.5) !important;
        box-shadow: 0 0 10px rgba(255, 0, 0, 0.6) !important;
    }

    /* Hide ads to keep the atmosphere clean */
    ytd-display-ad, ytd-promoted-sparkles-text {
        display: none !important;
    }

    /* Nuclear glow effect on hover for icons */
    ytd-thumbnail-overlay-time-status-renderer, ytd-video-primary-info-renderer #owner-name {
        text-shadow: 0 0 10px rgba(255, 0, 0, 0.7), 0 0 15px rgba(255, 0, 0, 0.8) !important;
    }

    /* Links and buttons in the comment section */
    yt-formatted-string, yt-simple-endpoint {
        color: #cccccc !important;
    }

    /* General text visibility */
    #content {
        color: #e6e6e6 !important;
        text-shadow: 0 0 5px #333, 0 0 10px #666 !important;
    }

    /* Create background with gloomy building silhouettes using a URL image */
    body {
        background: #1a1a1a url('https://wallpapercave.com/wp/wp9038221.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Create a subtle dark cloud effect */
    #content {
        background: url('https://www.transparenttextures.com/patterns/nuclear-winter.png') repeat !important;
    }
}
